      Twall = geometry->GetCustomBoundaryTemperature(val_marker, iVertex) / Temperature_Ref;
    }

    /*--- Compute the normal gradient in temperature using Twall ---*/

    su2double dTdn = -(There - Twall)/dist_ij;

    /*--- Apply a weak boundary condition for the energy equation.
     Compute the residual due to the prescribed heat flux. ---*/

    su2double Res_Conv = 0.0;
    su2double Res_Visc = thermal_conductivity * dTdn * Area;

    /*--- Calculate Jacobian for implicit time stepping ---*/

    if (implicit) {

      /*--- Add contributions to the Jacobian from the weak enforcement of the energy equations. ---*/

      su2double Density = nodes->GetDensity(iPoint);
      su2double Vel2 = GeometryToolbox::SquaredNorm(nDim, &nodes->GetPrimitive(iPoint)[prim_idx.Velocity()]);
      su2double dTdrho = 1.0/Density * ( -Twall + (Gamma-1.0)/Gas_Constant*(Vel2/2.0) );
      su2double dTdrhoE = (Gamma-1.0)/(Gas_Constant*Density);
      if (config->GetKind_FluidModel() == IDEAL_AIR_VARIABLE_CP) {
        // 原生弱壁面近似对角预条件，采用同阶段实际状态和冻结k的热力学链式导数。
        const su2double* secondary = nodes->GetSecondary(iPoint);
        dTdrho = secondary[2] + secondary[3]*(Vel2-nodes->GetEnergy(iPoint))/Density;
        dTdrhoE = secondary[3]/Density;
      }

      Jacobian_i[nDim+1][0] = thermal_conductivity/dist_ij * dTdrho * Area;

      for (auto jDim = 0u; jDim < nDim; jDim++)
        Jacobian_i[nDim+1][jDim+1] = 0.0;

      Jacobian_i[nDim+1][nDim+1] = thermal_conductivity/dist_ij * dTdrhoE * Area;
    }

    /*--- If the wall is moving, there are additional residual contributions
     due to pressure (p v_wall.n) and shear stress (tau.v_wall.n). ---*/

    if (dynamic_grid) {
      AddDynamicGridResidualContribution(iPoint, Point_Normal, geometry, UnitNormal,
                                         Area, geometry->nodes->GetGridVel(iPoint),
                                         Jacobian_i, Res_Conv, Res_Visc);
    }

    /*--- Convective and viscous contributions to the residual at the wall ---*/

    LinSysRes(iPoint, nDim+1) += Res_Conv - Res_Visc;

    /*--- Enforce the no-slip boundary condition in a strong way by
     modifying the velocity-rows of the Jacobian (1 on the diagonal).
     And add the contributions to the Jacobian due to energy. ---*/

    if (implicit) {
      Jacobian.AddBlock2Diag(iPoint, Jacobian_i);

      for (auto iVar = 1u; iVar <= nDim; iVar++) {
        Jacobian.DeleteValsRowi(iPoint, iVar);
      }
    }
  }
  END_SU2_OMP_FOR

  if (Jacobian_i)
    for (auto iVar = 0u; iVar < nVar; iVar++)
      delete [] Jacobian_i[iVar];
  delete [] Jacobian_i;

bool CNSVariable::SetPrimVar(unsigned long iPoint, su2double eddy_visc, su2double turb_ke, CFluidModel *FluidModel) {

  // 直接捕获热状态计算输入，包含原生回退后的同一次调用。
  FlowPrimitiveK(iPoint) = turb_ke;

  bool RightVol = true;

  SetVelocity(iPoint); // Computes velocity and velocity^2
  su2double density      = GetDensity(iPoint);
  su2double staticEnergy = GetEnergy(iPoint)-0.5*Velocity2(iPoint) - turb_ke;

  /*--- Check will be moved inside fluid model plus error description strings ---*/

  // 模块一。新物性拒绝候选态时，进入原生旧态恢复，避免读取旧物性字段。
  bool air_state_rejected = false;
  std::string rejected_reason;
  try {
    FluidModel->SetTDState_rhoe(density, staticEnergy);
  } catch (const std::domain_error& error) {
    if (dynamic_cast<CSU2IdealAir*>(FluidModel) == nullptr) throw;
    air_state_rejected = true;
    rejected_reason = error.what();
  }

  bool check_dens  = air_state_rejected || SetDensity(iPoint);
  bool check_press = air_state_rejected || SetPressure(iPoint, FluidModel->GetPressure());
  bool check_sos   = air_state_rejected || SetSoundSpeed(iPoint, FluidModel->GetSoundSpeed2());
  bool check_temp  = air_state_rejected || SetTemperature(iPoint, FluidModel->GetTemperature());

  /*--- Check that the solution has a physical meaning ---*/

  if (check_dens || check_press || check_sos  || check_temp) {

    // 模块二。失败证据使用明确的局部编号，保留原始全部守恒量与当前k。
    std::array<double, 5> trial{}, restored{};
    for (unsigned long iVar = 0; iVar < nVar; ++iVar) {
      trial[iVar] = Solution(iPoint,iVar);
      restored[iVar] = Solution_Old(iPoint,iVar);
    }
    if (nDim == 2) {
      trial[4] = trial[3]; trial[3] = 0.0;
      restored[4] = restored[3]; restored[3] = 0.0;
    }
    const double trial_energy = staticEnergy;

    /*--- Copy the old solution ---*/

    for (unsigned long iVar = 0; iVar < nVar; iVar++)
      Solution(iPoint,iVar) = Solution_Old(iPoint,iVar);

    /*--- Recompute the primitive variables ---*/

    SetVelocity(iPoint); // Computes velocity and velocity^2
    density      = GetDensity(iPoint);
    staticEnergy = GetEnergy(iPoint)-0.5*Velocity2(iPoint) - turb_ke;

    /*--- Check will be moved inside fluid model plus error description strings ---*/

    // 模块三。旧守恒态必须与本次实际k共同通过完整物性查询，否则明确终止。
    try {
      FluidModel->SetTDState_rhoe(density, staticEnergy);
    } catch (const std::domain_error& error) {
      if (dynamic_cast<CSU2IdealAir*>(FluidModel) != nullptr)
        rah_admissibility::record(iPoint, nDim, trial.data(), restored.data(),
                                  trial_energy, staticEnergy, turb_ke, false, error.what());
      throw;
    }
    if (air_state_rejected)
      rah_admissibility::record(iPoint, nDim, trial.data(), restored.data(),
                                trial_energy, staticEnergy, turb_ke, true, rejected_reason.c_str());

    SetDensity(iPoint);
    SetPressure(iPoint, FluidModel->GetPressure());
    SetSoundSpeed(iPoint, FluidModel->GetSoundSpeed2());
    SetTemperature(iPoint, FluidModel->GetTemperature());

    RightVol = false;

  }

  /*--- Set enthalpy ---*/

  SetEnthalpy(iPoint); // Requires pressure computation.

  /*--- Set laminar viscosity ---*/

  SetLaminarViscosity(iPoint, FluidModel->GetLaminarViscosity());

const bool neg_spalart_allmaras = config->GetSAParsedOptions().version == SA_OPTIONS::NEG;

/*--- Compute eddy viscosity ---*/

AD::StartNoSharedReading();

SU2_OMP_FOR_STAT(omp_chunk_size)
for (unsigned long iPoint = 0; iPoint < nPoint; iPoint ++) {

  const su2double rho = solver_container[FLOW_SOL]->GetNodes()->GetDensity(iPoint);
  const su2double mu = solver_container[FLOW_SOL]->GetNodes()->GetLaminarViscosity(iPoint);

  const su2double nu = mu/rho;
  const su2double nu_hat = nodes->GetSolution(iPoint,0);
  const su2double roughness = geometry->nodes->GetRoughnessHeight(iPoint);
  const su2double dist = geometry->nodes->GetWall_Distance(iPoint) + rough_const * roughness;

  su2double Ji = nu_hat/nu;
  if (roughness > 1.0e-10)
    Ji += cR1*roughness/(dist+EPS);

  const su2double Ji_3 = Ji*Ji*Ji;
  const su2double fv1  = Ji_3/(Ji_3+cv1_3);

  su2double muT = rho*fv1*nu_hat;

  if (neg_spalart_allmaras && nu_hat < 0) muT = 0.0;

  nodes->SetmuT(iPoint,muT);

}

void CTurbSASolver::BC_HeatFlux_Wall(CGeometry *geometry, CSolver **solver_container, CNumerics *conv_numerics,
                                     CNumerics *visc_numerics, CConfig *config, unsigned short val_marker) {
  SU2_ZONE_SCOPED

  /*--- Evaluate nu tilde at the closest point to the surface using the wall functions. ---*/

  if (config->GetWall_Functions()) {
    SU2_OMP_SAFE_GLOBAL_ACCESS(SetTurbVars_WF(geometry, solver_container, config, val_marker);)
    return;
  }

  const bool implicit = (config->GetKind_TimeIntScheme() == EULER_IMPLICIT);
  string Marker_Tag = config->GetMarker_All_TagBound(val_marker);
  WALL_TYPE WallType;
  su2double Roughness_Height;
  tie(WallType, Roughness_Height) = config->GetWallRoughnessProperties(Marker_Tag);
  Roughness_Height = max(Roughness_Height, EPS);

  /*--- The dirichlet condition is used only without wall function, otherwise the
   convergence is compromised as we are providing nu tilde values for the
   first point of the wall  ---*/

  SU2_OMP_FOR_STAT(OMP_MIN_SIZE)
  for (auto iVertex = 0u; iVertex < geometry->nVertex[val_marker]; iVertex++) {

    const auto iPoint = geometry->vertex[val_marker][iVertex]->GetNode();

    /*--- Check if the node belongs to the domain (i.e, not a halo node) ---*/

    if (!geometry->nodes->GetDomain(iPoint)) continue;

    if (WallType == WALL_TYPE::SMOOTH) {
      for (auto iVar = 0u; iVar < nVar; iVar++)
        nodes->SetSolution_Old(iPoint,iVar,0.0);

      LinSysRes.SetBlock_Zero(iPoint);

      /*--- Includes 1 in the diagonal ---*/

                                       CNumerics *visc_numerics, CConfig *config, unsigned short val_marker) {
  SU2_ZONE_SCOPED

  BC_HeatFlux_Wall(geometry, solver_container, conv_numerics, visc_numerics, config, val_marker);

}

void CTurbSASolver::BC_Inlet(CGeometry *geometry, CSolver **solver_container, CNumerics*, CNumerics*,
                             CConfig *config, unsigned short val_marker) {
  SU2_ZONE_SCOPED

  auto* flowSolver = solver_container[FLOW_SOL];
  CFluidModel* FluidModel = flowSolver->GetFluidModel();
  const su2double* Turb_Properties = config->GetInlet_TurbVal(config->GetMarker_All_TagBound(val_marker));
  const su2double Nu_Factor = Turb_Properties[0];
  const su2double* Scalar_Inlet = config->GetKind_Species_Model() != SPECIES_MODEL::NONE
                                      ? config->GetInlet_SpeciesVal(config->GetMarker_All_TagBound(val_marker))
                                      : nullptr;

  SU2_OMP_FOR_STAT(OMP_MIN_SIZE)
  for (auto iVertex = 0u; iVertex < geometry->nVertex[val_marker]; iVertex++) {
    su2double nuTilde = Inlet_TurbVars[val_marker][iVertex][0];
    const auto* V_inlet = flowSolver->GetCharacPrimVar(val_marker, iVertex);

    /*--- Non-dimensionalize Inlet_TurbVars if Inlet-Files are used. ---*/
    if (config->GetInlet_Profile_From_File()) {
      nuTilde *= config->GetDensity_Ref() / config->GetViscosity_Ref();
    } else {
      /*--- Fluid model evaluation of the inlet nu tilde. ---*/
      su2double Density_Inlet;
      if (config->GetKind_Regime() == ENUM_REGIME::COMPRESSIBLE) {
        Density_Inlet = V_inlet[prim_idx.Density()];
        FluidModel->SetTDState_Prho(V_inlet[prim_idx.Pressure()], Density_Inlet);
      } else {
        FluidModel->SetTDState_T(V_inlet[prim_idx.Temperature()], Scalar_Inlet);
        Density_Inlet = FluidModel->GetDensity();
      }
      const su2double Laminar_Viscosity_Inlet = FluidModel->GetLaminarViscosity();
      nuTilde = Nu_Factor * Laminar_Viscosity_Inlet / Density_Inlet;
      if (config->GetSAParsedOptions().bc) nuTilde *= 0.005;
    }
    ghostNodes->SetSolution(iVertex, 0, nuTilde);

    SetGhostPrimitives(iVertex, V_inlet);

    SetGhostGeometry(geometry, val_marker, iVertex);
  }
  END_SU2_OMP_FOR

  /*--- The diffusive term at this boundary causes serious convergence problems. ---*/
  BoundaryFlux(geometry, solver_container, config,
               ScalarFluxOptions::BoundaryConvective(*config, config->GetBounded_Turb()), val_marker);
}

template<class VariableType>
void CScalarSolver<VariableType>::BC_Riemann(CGeometry *geometry, CSolver **solver_container, CNumerics *conv_numerics, CNumerics *visc_numerics, CConfig *config, unsigned short val_marker) {
  SU2_ZONE_SCOPED

  string Marker_Tag         = config->GetMarker_All_TagBound(val_marker);

  switch(config->GetKind_Data_Riemann(Marker_Tag))
  {
  case TOTAL_CONDITIONS_PT: case STATIC_SUPERSONIC_INFLOW_PT: case STATIC_SUPERSONIC_INFLOW_PD: case DENSITY_VELOCITY:
    BC_Inlet(geometry, solver_container, conv_numerics, visc_numerics, config, val_marker);
    break;
  case STATIC_PRESSURE:
    BC_Outlet(geometry, solver_container, conv_numerics, visc_numerics, config, val_marker);
    break;
  }
}

template <class VariableType>
void CScalarSolver<VariableType>::BC_Periodic(CGeometry* geometry, CSolver** solver_container, CNumerics* numerics,
                                              CConfig* config) {
  SU2_ZONE_SCOPED

  UnitNormal[iDim] = Normal[iDim]/Area;

/*--- Primitive variables at point i ---*/

Velocity2_i = 0.0;
for (iDim = 0; iDim < nDim; iDim++) {
  Velocity_i[iDim] = V_i[iDim+1];
  Velocity2_i += Velocity_i[iDim]*Velocity_i[iDim];
}

Pressure_i = V_i[nDim+1];
Density_i = V_i[nDim+2];
Enthalpy_i = V_i[nDim+3];
Energy_i = Enthalpy_i - Pressure_i/Density_i;
StaticEnthalpy_i = Enthalpy_i - 0.5*Velocity2_i;
StaticEnergy_i = StaticEnthalpy_i - Pressure_i/Density_i;

Kappa_i = S_i[1]/Density_i;
Chi_i = S_i[0] - Kappa_i*StaticEnergy_i;
SoundSpeed_i = sqrt(Chi_i + StaticEnthalpy_i*Kappa_i);

/*--- Primitive variables at point j ---*/

Velocity2_j = 0.0;
for (iDim = 0; iDim < nDim; iDim++) {
  Velocity_j[iDim] = V_j[iDim+1];
  Velocity2_j += Velocity_j[iDim]*Velocity_j[iDim];
}

Pressure_j = V_j[nDim+1];
Density_j = V_j[nDim+2];
Enthalpy_j = V_j[nDim+3];
Energy_j = Enthalpy_j - Pressure_j/Density_j;

StaticEnthalpy_j = Enthalpy_j - 0.5*Velocity2_j;
StaticEnergy_j = StaticEnthalpy_j - Pressure_j/Density_j;

Kappa_j = S_j[1]/Density_j;
Chi_j = S_j[0] - Kappa_j*StaticEnergy_j;
SoundSpeed_j = sqrt(Chi_j + StaticEnthalpy_j*Kappa_j);

/*--- Recompute conservative variables ---*/

U_i[0] = Density_i; U_j[0] = Density_j;
for (iDim = 0; iDim < nDim; iDim++) {
  U_i[iDim+1] = Density_i*Velocity_i[iDim]; U_j[iDim+1] = Density_j*Velocity_j[iDim];
}
U_i[nDim+1] = Density_i*Energy_i; U_j[nDim+1] = Density_j*Energy_j;

/*--- Roe-averaged variables at interface between i & j ---*/

ComputeRoeAverage();

if (RoeSoundSpeed2 <= 0.0) {
  for (iVar = 0; iVar < nVar; iVar++) {
    Flux[iVar] = 0.0;
    for (jVar = 0; jVar < nVar; jVar++) {
    Jacobian_i[iVar][iVar] = 0.0;
    Jacobian_j[iVar][iVar] = 0.0;
    }
  }
  AD::SetPreaccOut(Flux, nVar);
  AD::EndPreacc();

  return ResidualType<>(Flux, Jacobian_i, Jacobian_j);
}

RoeSoundSpeed = sqrt(RoeSoundSpeed2);

/*--- Compute ProjFlux_i ---*/
GetInviscidProjFlux(&Density_i, Velocity_i, &Pressure_i, &Enthalpy_i, Normal, ProjFlux_i);

/*--- Compute ProjFlux_j ---*/
GetInviscidProjFlux(&Density_j, Velocity_j, &Pressure_j, &Enthalpy_j, Normal, ProjFlux_j);

/*--- Compute P and Lambda (do it with the Normal) ---*/

GetPMatrix(&RoeDensity, RoeVelocity, &RoeSoundSpeed, &RoeEnthalpy, &RoeChi, &RoeKappa, UnitNormal, P_Tensor);

